import org.jsoup.Connection;
import org.jsoup.helper.StringUtil;
import org.junit.Test;

import java.net.MalformedURLException;
import java.net.URL;
import java.io.UnsupportedEncodingException;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class UrlBuilderTest {

    @Test
    public void build_NullQueryAndRefTest() throws MalformedURLException {
        URL inputUrl = new URL("http://google.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL outputUrl = urlBuilder.build();
        assertEquals(inputUrl, outputUrl);
    }

    @Test
    public void build_NonNullQueryAndRefTest() throws MalformedURLException {
        URL inputUrl = new URL("http://google.com?query=value#ref");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL outputUrl = urlBuilder.build();
        assertNotEquals(inputUrl, outputUrl);
    }

    @Test(expected = MalformedURLException.class)
    public void build_InvalidProtocolTest() throws MalformedURLException {
        URL inputUrl = new URL("htt://google.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        urlBuilder.build();
    }

    @Test
    public void UrlBuilder_ValidUrlTest() throws MalformedURLException {
        URL inputUrl = new URL("http://google.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals(inputUrl, urlBuilder.u);
    }

    @Test
    public void appendKeyVal_NormalTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("http://google.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = new Connection.KeyVal("name", "John");
        urlBuilder.appendKeyVal(kv);
        assertEquals("?name=John", urlBuilder.q.toString());
    }

    @Test
    public void appendKeyVal_MultipleQueriesTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("http://google.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv1 = new Connection.KeyVal("name", "John");
        urlBuilder.appendKeyVal(kv1);
        Connection.KeyVal kv2 = new Connection.KeyVal("age", "25");
        urlBuilder.appendKeyVal(kv2);
        assertEquals("?name=John&age=25", urlBuilder.q.toString());
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyVal_UnsupportedEncodingTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("http://google.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = new Connection.KeyVal("\u0000", "\u0001");
        urlBuilder.appendKeyVal(kv);
    }
}
